"use strict";
const crypto = require('crypto');
const http = require('http');
const url = require('url');

// Secure token store with hashed passwords
const TOKEN_STORE = new Map();
const SESSION_STORE = new Map();
const RATE_LIMIT = new Map();

const CONFIG = {
  MAX_USERNAME_LEN: 64,
  MAX_PASSWORD_LEN: 128,
  SESSION_TTL: 3600000,
  RATE_LIMIT_WINDOW: 60000,
  RATE_LIMIT_MAX: 10,
  MAX_BODY_SIZE: 4096,
  ALLOWED_ROLES: ['user', 'admin', 'moderator']
};

// Simulated user database with role-based access.
// Passwords are stored as scrypt-derived values in the form: salt(hex):hash(hex)
// (In production a vetted library such as bcrypt/argon2 would be used.)
function deriveHash(password, salt) {
  return crypto.scryptSync(password, salt, 64).toString('hex');
}

function makeStoredPassword(password) {
  const salt = crypto.randomBytes(16).toString('hex');
  return `${salt}:${deriveHash(password, salt)}`;
}

// Demo credentials seeded deterministically at startup.
const USERS_DB = new Map([
  ['admin', { passwordHash: makeStoredPassword('admin-demo-password'), role: 'admin' }],
  ['alice', { passwordHash: makeStoredPassword('alice-demo-password'), role: 'user' }],
  ['moderator', { passwordHash: makeStoredPassword('moderator-demo-password'), role: 'moderator' }]
]);

// Access control list for protected resources
const ACL = {
  '/api/users': ['admin'],
  '/api/settings': ['admin', 'moderator'],
  '/api/profile': ['user', 'admin', 'moderator'],
  '/api/data': ['user', 'admin', 'moderator']
};

function verifyPassword(password, storedPassword) {
  if (typeof storedPassword !== 'string' || !storedPassword.includes(':')) return false;
  const [salt, expectedHex] = storedPassword.split(':');
  const expected = Buffer.from(expectedHex, 'hex');
  let actual;
  try {
    actual = crypto.scryptSync(password, salt, expected.length);
  } catch (e) {
    return false;
  }
  if (actual.length !== expected.length) return false;
  return crypto.timingSafeEqual(actual, expected);
}

function canonicalizeUsername(input) {
  if (typeof input !== 'string') return '';
  // Apply Unicode NFKC normalization FIRST, before any other processing
  // This is the single canonical form used for ALL purposes
  let canonical = input.normalize('NFKC');
  // Remove zero-width characters that could bypass checks
  canonical = canonical.replace(/[\u200B-\u200F\u2028-\u202F\uFEFF]/g, '');
  // Strip leading/trailing whitespace
  canonical = canonical.trim();
  // Limit length
  if (canonical.length > CONFIG.MAX_USERNAME_LEN) {
    canonical = canonical.substring(0, CONFIG.MAX_USERNAME_LEN);
  }
  // Convert to lowercase for case-insensitive matching
  canonical = canonical.toLowerCase();
  return canonical;
}

function validateAndLookupUser(rawUsername) {
  // Single canonicalization step - one identity used for BOTH lookup and auth
  const canonicalName = canonicalizeUsername(rawUsername);
  if (canonicalName.length === 0) return null;

  // Validate username contains only allowed characters after normalization
  if (!/^[a-z0-9._-]+$/.test(canonicalName)) return null;

  // Look up user in database using canonical form
  const user = USERS_DB.get(canonicalName);
  if (!user) return null;

  // The same canonical name is used for both ACL checks and DB lookup
  return { authIdentity: canonicalName, role: user.role, lookupKey: canonicalName, passwordHash: user.passwordHash };
}

function checkRateLimit(ip) {
  const now = Date.now();
  const record = RATE_LIMIT.get(ip);
  if (!record || (now - record.windowStart) > CONFIG.RATE_LIMIT_WINDOW) {
    RATE_LIMIT.set(ip, { windowStart: now, count: 1 });
    return true;
  }
  if (record.count >= CONFIG.RATE_LIMIT_MAX) return false;
  record.count++;
  return true;
}

function generateSession(userInfo) {
  const sessionId = crypto.randomBytes(32).toString('hex');
  SESSION_STORE.set(sessionId, {
    authIdentity: userInfo.authIdentity,
    role: userInfo.role,
    createdAt: Date.now()
  });
  return sessionId;
}

function validateSession(sessionId) {
  if (!sessionId || typeof sessionId !== 'string') return null;
  const session = SESSION_STORE.get(sessionId);
  if (!session) return null;
  if ((Date.now() - session.createdAt) > CONFIG.SESSION_TTL) {
    SESSION_STORE.delete(sessionId);
    return null;
  }
  return session;
}

function checkAuthorization(session, path) {
  const requiredRoles = ACL[path];
  if (!requiredRoles) return false; // No ACL entry = deny by default
  return requiredRoles.includes(session.role);
}

function handleLogin(req, res, body) {
  const ip = req.socket.remoteAddress;
  if (!checkRateLimit(ip)) {
    res.writeHead(429);
    res.end(JSON.stringify({ error: 'Rate limited' }));
    return;
  }

  let parsed;
  try {
    parsed = JSON.parse(body);
  } catch (e) {
    res.writeHead(400);
    res.end(JSON.stringify({ error: 'Invalid JSON' }));
    return;
  }

  const { username, password } = parsed;
  if (!username || !password) {
    res.writeHead(400);
    res.end(JSON.stringify({ error: 'Missing credentials' }));
    return;
  }

  if (typeof username !== 'string' || typeof password !== 'string') {
    res.writeHead(400);
    res.end(JSON.stringify({ error: 'Invalid credential types' }));
    return;
  }

  if (password.length > CONFIG.MAX_PASSWORD_LEN) {
    res.writeHead(400);
    res.end(JSON.stringify({ error: 'Password too long' }));
    return;
  }

  const userInfo = validateAndLookupUser(username);
  // Verify the password against the stored hash. Failure for either an unknown
  // user or a wrong password results in the same generic response.
  const passwordOk = userInfo ? verifyPassword(password, userInfo.passwordHash) : false;
  if (!userInfo || !passwordOk) {
    // Constant-time-ish delay to reduce timing/enumeration signal
    setTimeout(() => {
      res.writeHead(401);
      res.end(JSON.stringify({ error: 'Invalid credentials' }));
    }, 100);
    return;
  }

  const sessionId = generateSession(userInfo);
  res.writeHead(200, { 'Set-Cookie': `session=${sessionId}; HttpOnly; Secure; SameSite=Strict` });
  res.end(JSON.stringify({ success: true, role: userInfo.role }));
}

function handleProtectedResource(req, res) {
  const cookies = (req.headers.cookie || '').split(';').reduce((acc, c) => {
    const [key, ...valParts] = c.trim().split('=');
    const val = valParts.join('=');
    if (key && val) acc[key] = val;
    return acc;
  }, {});

  const session = validateSession(cookies.session);
  if (!session) {
    res.writeHead(401);
    res.end(JSON.stringify({ error: 'Unauthorized' }));
    return;
  }

  const parsedUrl = url.parse(req.url, true);
  // Normalize the path to prevent traversal
  const normalizedPath = parsedUrl.pathname.replace(/\/+/g, '/').replace(/\.\.\//g, '');

  if (!checkAuthorization(session, normalizedPath)) {
    res.writeHead(403);
    res.end(JSON.stringify({ error: 'Forbidden' }));
    return;
  }

  res.writeHead(200);
  res.end(JSON.stringify({ data: 'protected content', user: session.authIdentity, role: session.role }));
}

const server = http.createServer((req, res) => {
  const parsedUrl = url.parse(req.url, true);

  if (req.method === 'POST' && parsedUrl.pathname === '/login') {
    let body = '';
    let aborted = false;
    req.on('data', chunk => {
      if (aborted) return;
      // Enforce the size limit BEFORE appending, and abort the stream when exceeded.
      if (body.length + chunk.length > CONFIG.MAX_BODY_SIZE) {
        aborted = true;
        res.writeHead(413);
        res.end(JSON.stringify({ error: 'Payload too large' }));
        req.destroy();
        return;
      }
      body += chunk;
    });
    req.on('end', () => {
      if (aborted) return;
      handleLogin(req, res, body);
    });
  } else if (req.method === 'GET' && parsedUrl.pathname.startsWith('/api/')) {
    handleProtectedResource(req, res);
  } else {
    res.writeHead(404);
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

if (require.main === module) {
  server.listen(3000, '127.0.0.1');
}

module.exports = { validateAndLookupUser, canonicalizeUsername, server };
